// Monta a avaliação de cada pedido para a IA (um item por pedido).
const out = [];
const lista = $input.all().map(i => i.json).flatMap(x => Array.isArray(x) ? x : [x]).filter(x => x && x.id && x.pedido);
const sys = [
  'Você é o agente de produto do Dyno, um assessor pessoal no WhatsApp (finanças por texto/áudio/foto, contas a pagar, lembretes que insistem, tarefas e listas, agenda, rastreio de encomendas dos Correios, câmbio, remédios, modo família, painel web). Também existe o Dyno Business (orçamentos em PDF para pequenos negócios).',
  'Momento da empresa: Beta com cerca de 17 clientes, um único desenvolvedor (Daniel com o Claude), stack n8n + Supabase + Evolution API + OpenAI. Princípio atual: "Simplifique, valide, escale" — funções novas só entram se reforçam o problema central (controle de gastos e contas sem app) ou se muitos clientes pedem; até 06/11 a regra é congelar o que não for essencial.',
  'Avalie o pedido de um cliente e responda SÓ em JSON: {"veredito":"vale"|"talvez"|"nao_agora","motivo":"2 frases objetivas","como":"como implantar em 1 frase (API/fonte de dados, gratuita ou paga)","esforco":"pequeno"|"médio"|"grande","custo":"grátis"|"baixo"|"pago","como_usar":"1 frase para o cliente de como usar quando ficar pronto"}.',
  'Critérios: valor para o cliente e para a retenção, quantos clientes já pediram algo parecido, custo e risco (dados sensíveis, APIs pagas, scraping frágil), esforço. Seja honesto: diga nao_agora quando não compensar agora. Não invente APIs; se não souber de uma fonte gratuita confiável, diga.'
].join('\n');
for (const f of lista) {
  const user = 'Pedido #' + f.id + ' de ' + (f.autor || 'cliente') + ': ' + f.pedido + (f.categoria ? ' (categoria: ' + f.categoria + ')' : '') +
    (f.texto_usuario ? '\nMensagem original: "' + f.texto_usuario + '"' : '') +
    '\nClientes que já pediram algo da mesma categoria: ' + (f.mesma_categoria || 1) +
    ((f.parecidos || []).length ? '\nPedidos parecidos: ' + f.parecidos.join(' | ') : '');
  out.push({ json: { id: f.id, payload: { model: 'gpt-6-luna', reasoning_effort: 'low', response_format: { type: 'json_object' }, messages: [{ role: 'system', content: sys }, { role: 'user', content: user }] } } });
}
return out;

// Junta a resposta da IA com o id do pedido.
const out = [];
const ids = $('Montar avaliação').all().map(i => i.json.id);
$input.all().forEach((it, k) => {
  let a = null;
  try { a = JSON.parse(it.json.choices[0].message.content); } catch (e) { a = null; }
  if (!a) a = { veredito: 'talvez', motivo: 'Não consegui avaliar automaticamente; vale olhar com calma.', como: '', esforco: '?', custo: '?', como_usar: '' };
  out.push({ json: { p_id: ids[k], p_avaliacao: a } });
});
return out;
